local b='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
local t={}
for i=1,64 do t[b:sub(i,i)]=i-1 end
local k=string.char(190,119,18,17,135,228,4,25,34,155,94,215,164,84,152,57,105,242,97,219,213,250,247,138,248,167,53,29,121,214,171,78)
local kn=#k
local function d(s)
    local o={}
    local n=#s
    local i=1
    while i<=n do
        local a=t[s:sub(i,i)] or 0
        local c=t[s:sub(i+1,i+1)] or 0
        local e=t[s:sub(i+2,i+2)] or 0
        local f=t[s:sub(i+3,i+3)] or 0
        o[#o+1]=string.char((a*4+math.floor(c/16))%256)
        if s:sub(i+2,i+2)~='=' then o[#o+1]=string.char((c*16+math.floor(e/4))%256) end
        if s:sub(i+3,i+3)~='=' then o[#o+1]=string.char((e*64+f)%256) end
        i=i+4
    end
    return table.concat(o)
end
local p=d('')
local o={}
for i=1,#p do
    o[i]=string.char(bit32.bxor(p:byte(i),k:byte((i-1)%kn+1)))
end
local src=table.concat(o)
o=nil
p=nil
local fn,err=loadstring(src)
if not fn then error(err) end
fn()